// Remove the lowered-pitch attribute (5) from the chosen section only,
// then start the pitch-up event for it.
ScMapPitchUp <- function ( idx )
{
	if (idx == 0)
	{
		CMND_BTL_DEL_FLOOR_ATTR("FL01", 5);
	}
	else if (idx == 1)
	{
		CMND_BTL_DEL_FLOOR_ATTR("FL02", 5);
	}

	CMND_BTL_TRIGGER_FLOOR_EV(FLOOR_EVT_PITCHUP, idx + 1);
};

// Attributes 1 to 4 are the quicksand depths; remove them from both halves
CMND_BTL_DEL_FLOOR_ATTR("FL01", 1);
CMND_BTL_DEL_FLOOR_ATTR("FL01", 2);
CMND_BTL_DEL_FLOOR_ATTR("FL01", 3);
CMND_BTL_DEL_FLOOR_ATTR("FL01", 4);
CMND_BTL_DEL_FLOOR_ATTR("FL02", 1);
CMND_BTL_DEL_FLOOR_ATTR("FL02", 2);
CMND_BTL_DEL_FLOOR_ATTR("FL02", 3);
CMND_BTL_DEL_FLOOR_ATTR("FL02", 4);
